/* ============================================================
   RE-MEDIA LUXURY DARK THEME (SCOPED TO body[data-page="home"])
   ============================================================ */
body[data-page="home"] {
  --bg: #05080d;
  --bg-deep: #04070b;
  --surface: #0a1018;
  --surface-raised: #0f1722;
  --accent: #4c92ff;
  --accent-soft: #83c0ff;
  --accent-glow: rgba(76, 146, 255, 0.35);
  --gold: #e8933c;
  --gold-soft: #ffc37a;
  --text: #f5f8fc;
  --muted: #a2b0c3;
  --line: rgba(255, 255, 255, 0.08);
  --header-h: 76px;
  --font-display: 'kaleko', 'Cormorant Garamond', Georgia, serif;
  --font-body: 'kaleko', 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-editorial: 'kaleko', 'Cormorant Garamond', Georgia, serif;

  background-color: var(--bg) !important;
  color: var(--text) !important;
  font-family: var(--font-body);
  overflow-x: hidden !important;
  max-width: 100vw !important;
}

/* Global Reset Guards */
html {
  overflow-x: hidden !important;
  max-width: 100vw !important;
  box-sizing: border-box;
}
*, *::before, *::after {
  box-sizing: inherit;
}

/* Buttons */
body[data-page="home"] .button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-body);
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  text-decoration: none;
  cursor: pointer;
  transition: transform .25s ease, box-shadow .25s ease, background .25s ease, border-color .25s ease;
  white-space: nowrap;
}
body[data-page="home"] .button-accent {
  background: linear-gradient(135deg, #4c92ff 0%, #2f73e8 100%);
  color: #ffffff !important;
  border: 1px solid rgba(131, 192, 255, 0.45);
  box-shadow: 0 10px 30px rgba(76, 146, 255, 0.35), 0 0 20px rgba(76, 146, 255, 0.2);
}
body[data-page="home"] .button-accent:hover {
  transform: translateY(-2px);
  background: linear-gradient(135deg, #6ba5ff 0%, #3e81f5 100%);
  box-shadow: 0 14px 38px rgba(76, 146, 255, 0.45), 0 0 28px rgba(131, 192, 255, 0.3);
}
body[data-page="home"] .button-outline {
  background: linear-gradient(135deg, rgba(255, 255, 255, 0.06), rgba(255, 255, 255, 0.02));
  color: #f5f8fc !important;
  border: 1px solid rgba(255, 255, 255, 0.16);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.25);
}
body[data-page="home"] .button-outline:hover {
  transform: translateY(-2px);
  border-color: rgba(131, 192, 255, 0.4);
  background: linear-gradient(135deg, rgba(76, 146, 255, 0.15), rgba(255, 255, 255, 0.04));
  box-shadow: 0 14px 36px rgba(0, 0, 0, 0.35);
}

/* ============================================================
   HEADER: DESKTOP FLOATING PILL + MOBILE PINNED TOPBAR
   ============================================================ */
body[data-page="home"] .site-header--glass {
  position: fixed;
  top: 1.25rem;
  left: 0;
  right: 0;
  z-index: 1000;
  display: flex;
  justify-content: center;
  padding: 0 1rem;
  pointer-events: none;
  transition: transform .3s ease, top .3s ease;
}
body[data-page="home"] .site-header--glass .site-header__inner {
  pointer-events: auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
  width: 100%;
  max-width: 960px;
  height: 56px;
  padding: 0 1.25rem;
  background: rgba(8, 14, 24, 0.45) !important;
  backdrop-filter: blur(28px) saturate(180%) !important;
  -webkit-backdrop-filter: blur(28px) saturate(180%) !important;
  border: 1px solid rgba(255, 255, 255, 0.2) !important;
  border-radius: 9999px;
  box-shadow: 
    0 16px 40px rgba(0, 0, 0, 0.35),
    inset 0 1px 0 rgba(255, 255, 255, 0.3),
    inset 0 -1px 0 rgba(255, 255, 255, 0.06),
    0 0 24px rgba(76, 146, 255, 0.15) !important;
}
body[data-page="home"] .site-header__nav {
  display: flex;
  align-items: center;
  gap: 1.5rem;
}
body[data-page="home"] .header-link {
  font-family: var(--font-body);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--muted);
  text-decoration: none;
  transition: color .2s ease;
}
body[data-page="home"] .header-link:hover,
body[data-page="home"] .header-link.active {
  color: #f5f8fc;
}
body[data-page="home"] .site-header__brand {
  display: inline-flex;
  align-items: center;
  gap: 0.65rem;
  text-decoration: none;
}
body[data-page="home"] .site-header__brand-image {
  height: 34px;
  width: auto;
}
body[data-page="home"] .site-header__brand-text {
  font-family: var(--font-display);
  font-size: 1.05rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  color: #f5f8fc;
  display: flex;
  flex-direction: column;
  line-height: 1;
}
body[data-page="home"] .site-header__brand-text small {
  font-family: var(--font-body);
  font-size: 0.52rem;
  letter-spacing: 0.12em;
  color: var(--accent-soft);
  text-transform: uppercase;
  margin-top: 3px;
