/* ==========================================================================
   ATENA CTA BANNER ("YOUR VISION, BUILT" - CONSULTATION)
   ========================================================================== */
.cta-banner {
  position: relative;
  min-height: 58vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  overflow: hidden;
  padding: 110px 24px;
  background: #070d22;
}

.banner-media {
  position: absolute;
  inset: -10% 0;
  z-index: 0;
  background-image: url('../img/projects/ext-rear.jpg');
  background-size: cover;
  background-position: center;
  will-change: transform;
}

.banner-scrim {
  position: absolute;
  inset: 0;
  z-index: 1;
  background: linear-gradient(180deg, rgba(7, 13, 34, 0.74) 0%, rgba(7, 13, 34, 0.86) 100%);
  backdrop-filter: blur(1.5px);
  -webkit-backdrop-filter: blur(1.5px);
}

.banner-inner {
  position: relative;
  z-index: 2;
  padding: 0 20px;
  max-width: 820px;
  margin: 0 auto;
}

.banner-inner .eyebrow {
  font-size: 0.76rem;
  letter-spacing: 0.32em;
  text-transform: uppercase;
  color: #39bce8;
  font-weight: 700;
  margin-bottom: 22px;
  display: inline-flex;
  align-items: center;
  gap: 12px;
}

.banner-inner .eyebrow::before {
  content: "";
  width: 36px;
  height: 2px;
  background: #39bce8;
  display: inline-block;
  border-radius: 2px;
}

.banner-inner h2 {
  font-size: clamp(2.2rem, 5vw, 3.8rem);
  font-weight: 800;
  line-height: 1.15;
  color: #ffffff;
  margin-bottom: 22px;
  letter-spacing: -0.02em;
  font-family: 'Plus Jakarta Sans', var(--font-display), sans-serif;
  text-shadow: 0 4px 20px rgba(0, 0, 0, 0.5);
}

.banner-inner p {
  color: rgba(232, 241, 253, 0.88);
  font-weight: 400;
  margin-bottom: 36px;
  font-size: clamp(1.05rem, 2vw, 1.2rem);
  line-height: 1.6;
  max-width: 680px;
  margin-left: auto;
  margin-right: auto;
  text-shadow: 0 2px 10px rgba(0, 0, 0, 0.4);
}

.bts-cta-btn {
  font-size: 0.84rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  font-weight: 700;
  cursor: pointer;
  border: none;
  padding: 16px 38px;
  border-radius: 999px;
  background: linear-gradient(135deg, #39bce8 0%, #2a4ed6 100%);
  color: #ffffff !important;
  text-decoration: none !important;
  transition: all 0.35s cubic-bezier(0.16, 1, 0.3, 1);
  box-shadow: 0 8px 32px -4px rgba(42, 78, 214, 0.65), 0 0 20px rgba(57, 188, 232, 0.4);
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.bts-cta-btn:hover {
  transform: translateY(-3px) scale(1.02);
  box-shadow: 0 14px 44px -4px rgba(42, 78, 214, 0.85), 0 0 30px rgba(57, 188, 232, 0.6);
  color: #ffffff !important;
}

@media (max-width: 768px) {
  .cta-banner {
    padding: 80px 18px;
    min-height: 50vh;
  }
  .banner-inner h2 {
    font-size: clamp(1.8rem, 7vw, 2.6rem);
    margin-bottom: 16px;
  }
  .banner-inner p {
    font-size: 1rem;
    margin-bottom: 28px;
  }
  .bts-cta-btn {
    width: 100%;
    max-width: 340px;
    padding: 15px 24px;
    font-size: 0.82rem;
  }
}


