  border-radius: 9999px;
  filter: blur(80px);
  pointer-events: none;
  z-index: 1;
  opacity: 0.16;
}
body[data-page="home"] .hero__orb--one {
  top: 15%;
  left: 50%;
  transform: translateX(-50%);
  width: min(650px, 90vw);
  height: 320px;
  background: radial-gradient(circle, rgba(76, 146, 255, 0.2), rgba(76, 146, 255, 0));
}
body[data-page="home"] .hero__orb--two {
  bottom: 10%;
  left: 50%;
  transform: translateX(-50%);
  width: min(500px, 80vw);
  height: 250px;
  background: radial-gradient(circle, rgba(131, 192, 255, 0.12), rgba(131, 192, 255, 0));
}

body[data-page="home"] .hero__fade {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 78%, #05080d 100%);
  z-index: 1;
  pointer-events: none;
}

body[data-page="home"] .hero__content {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100% !important;
  max-width: 1000px !important;
  margin: 0 auto !important;
  padding: 0 1rem !important;
  box-sizing: border-box !important;
}

body[data-page="home"] .hero__stack {
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  text-align: center !important;
  width: 100% !important;
  max-width: 900px !important;
  margin: 0 auto !important;
  gap: 1.25rem !important;
  box-sizing: border-box !important;
}

body[data-page="home"] .hero__badge-wrap {
  display: flex;
  justify-content: center;
  width: 100%;
}

body[data-page="home"] .hero__badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 9999px;
  border: 1px solid rgba(131, 192, 255, 0.25);
  background: rgba(5, 11, 20, 0.72);
  backdrop-filter: blur(12px);
