/* ============================================================
   RE-MEDIA LUXURY DARK THEME (SCOPED TO body[data-page="home"])
   ============================================================ */
body[data-page="home"] {
  --bg: #05080d;
  --bg-deep: #04070b;
  --surface: #0a1018;
  --surface-raised: #0f1722;
  --accent: #4c92ff;
  --accent-soft: #83c0ff;
  --accent-glow: rgba(76, 146, 255, 0.35);
  --gold: #e8933c;
  --gold-soft: #ffc37a;
  --text: #f5f8fc;
  --muted: #a2b0c3;
  --line: rgba(255, 255, 255, 0.08);
  --header-h: 76px;
  --font-display: 'kaleko', 'Cormorant Garamond', Georgia, serif;
  --font-body: 'kaleko', 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-editorial: 'kaleko', 'Cormorant Garamond', Georgia, serif;

  background-color: var(--bg) !important;
  color: var(--text) !important;
  font-family: var(--font-body);
  overflow-x: hidden !important;
  max-width: 100vw !important;
}

/* Global Reset Guards */
html {
  overflow-x: hidden !important;
  max-width: 100vw !important;
  box-sizing: border-box;
}
*, *::before, *::after {
  box-sizing: inherit;
}

/* Buttons */
body[data-page="home"] .button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-body);
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  text-decoration: none;
  cursor: pointer;
  transition: transform .25s ease, box-shadow .25s ease, background .25s ease, border-color .25s ease;
  white-space: nowrap;
}
body[data-page="home"] .button-accent {
  background: linear-gradient(135deg, #4c92ff 0%, #2f73e8 100%);
  color: #ffffff !important;
  border: 1px solid rgba(131, 192, 255, 0.45);
  box-shadow: 0 10px 30px rgba(76, 146, 255, 0.35), 0 0 20px rgba(76, 146, 255, 0.2);
}
body[data-page="home"] .button-accent:hover {
  transform: translateY(-2px);
  background: linear-gradient(135deg, #6ba5ff 0%, #3e81f5 100%);
  box-shadow: 0 14px 38px rgba(76, 146, 255, 0.45), 0 0 28px rgba(131, 192, 255, 0.3);
}
body[data-page="home"] .button-outline {
  background: linear-gradient(135deg, rgba(255, 255, 255, 0.06), rgba(255, 255, 255, 0.02));
  color: #f5f8fc !important;
  border: 1px solid rgba(255, 255, 255, 0.16);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.25);
}
body[data-page="home"] .button-outline:hover {
  transform: translateY(-2px);
  border-color: rgba(131, 192, 255, 0.4);
  background: linear-gradient(135deg, rgba(76, 146, 255, 0.15), rgba(255, 255, 255, 0.04));
  box-shadow: 0 14px 36px rgba(0, 0, 0, 0.35);
}

/* ============================================================
   HEADER: DESKTOP FLOATING PILL + MOBILE PINNED TOPBAR
   ============================================================ */
body[data-page="home"] .site-header--glass {
  position: fixed;
  top: 1.25rem;
  left: 0;
  right: 0;
  z-index: 1000;
  display: flex;
  justify-content: center;
  padding: 0 1rem;
  pointer-events: none;
  transition: transform .3s ease, top .3s ease;
}
body[data-page="home"] .site-header--glass .site-header__inner {
  pointer-events: auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
  width: 100%;
  max-width: 960px;
  height: 56px;
  padding: 0 1.25rem;
  background: rgba(8, 14, 24, 0.45) !important;
  backdrop-filter: blur(28px) saturate(180%) !important;
  -webkit-backdrop-filter: blur(28px) saturate(180%) !important;
  border: 1px solid rgba(255, 255, 255, 0.2) !important;
  border-radius: 9999px;
  box-shadow: 
    0 16px 40px rgba(0, 0, 0, 0.35),
    inset 0 1px 0 rgba(255, 255, 255, 0.3),
    inset 0 -1px 0 rgba(255, 255, 255, 0.06),
    0 0 24px rgba(76, 146, 255, 0.15) !important;
}
body[data-page="home"] .site-header__nav {
  display: flex;
  align-items: center;
  gap: 1.5rem;
}
body[data-page="home"] .header-link {
  font-family: var(--font-body);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--muted);
  text-decoration: none;
  transition: color .2s ease;
}
body[data-page="home"] .header-link:hover,
body[data-page="home"] .header-link.active {
  color: #f5f8fc;
}
body[data-page="home"] .site-header__brand {
  display: inline-flex;
  align-items: center;
  gap: 0.65rem;
  text-decoration: none;
}
body[data-page="home"] .site-header__brand-image {
  height: 34px;
  width: auto;
}
body[data-page="home"] .site-header__brand-text {
  font-family: var(--font-display);
  font-size: 1.05rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  color: #f5f8fc;
  display: flex;
  flex-direction: column;
  line-height: 1;
}
body[data-page="home"] .site-header__brand-text small {
  font-family: var(--font-body);
  font-size: 0.52rem;
  letter-spacing: 0.12em;
  color: var(--accent-soft);
  text-transform: uppercase;
  margin-top: 3px;
  font-weight: 600;
}
body[data-page="home"] .header-btn {
  min-height: 2.35rem;
  padding: 0 1.25rem;
  font-size: 0.7rem;
  border-radius: 9999px;
}
body[data-page="home"] .site-header__mobile {
  display: none;
}
body[data-page="home"] .mobile-drawer {
  display: none;
}

/* Mobile Header Breakpoint (<= 860px) */
@media (max-width: 860px) {
  body[data-page="home"] .site-header--glass {
    top: 0;
    padding: 0;
    pointer-events: auto;
  }
  body[data-page="home"] .site-header--glass .site-header__inner {
    max-width: 100%;
    height: 60px;
    border-radius: 0;
    border: none;
    border-bottom: 1px solid rgba(255, 255, 255, 0.16) !important;
    background: rgba(8, 14, 24, 0.52) !important;
    backdrop-filter: blur(28px) saturate(180%) !important;
    -webkit-backdrop-filter: blur(28px) saturate(180%) !important;
    padding: 0 1rem;
    box-shadow: 
      0 8px 32px rgba(0, 0, 0, 0.35),
      inset 0 -1px 0 rgba(255, 255, 255, 0.08) !important;
  }
  body[data-page="home"] .site-header__nav {
    display: none !important;
  }
  body[data-page="home"] .site-header__brand:not(.site-header__brand--mobile) {
    display: none !important;
  }
  body[data-page="home"] .site-header__mobile {
    display: flex !important;
    align-items: center;
    justify-content: space-between;
    width: 100%;
  }
  body[data-page="home"] .site-header__brand--mobile {
    display: inline-flex !important;
    align-items: center;
    gap: 8px;
    text-decoration: none;
  }
  body[data-page="home"] .site-header__brand--mobile .site-header__brand-image {
    height: 30px;
  }
  body[data-page="home"] .site-header__brand--mobile .site-header__brand-text {
    font-size: 1.15rem;
    color: #f5f8fc;
    font-weight: 800;
  }
  body[data-page="home"] .header-btn-mob {
    display: none !important;
  }
  body[data-page="home"] .site-header__mobile-actions {
    display: none !important;
  }
  body[data-page="home"] .menu-button,
  body[data-page="home"] #hamburger {
    display: flex !important;
    flex-direction: column !important;
    justify-content: center !important;
    align-items: center !important;
    gap: 5px !important;
    width: 44px !important;
    height: 44px !important;
    background: rgba(255, 255, 255, 0.08) !important;
    backdrop-filter: blur(16px) !important;
    -webkit-backdrop-filter: blur(16px) !important;
    border: 1px solid rgba(255, 255, 255, 0.22) !important;
    border-radius: 12px !important;
    cursor: pointer !important;
    padding: 0 !important;
    position: relative !important;
    box-shadow: 
      0 4px 16px rgba(0, 0, 0, 0.25),
      inset 0 1px 0 rgba(255, 255, 255, 0.28) !important;
    transition: background .2s ease, border-color .2s ease, box-shadow .2s ease !important;
  }
  body[data-page="home"] .menu-button:hover,
  body[data-page="home"] #hamburger:hover {
    background: rgba(255, 255, 255, 0.16) !important;
    border-color: rgba(131, 192, 255, 0.45) !important;
    box-shadow: 
      0 6px 20px rgba(76, 146, 255, 0.25),
      inset 0 1px 0 rgba(255, 255, 255, 0.4) !important;
  }
  body[data-page="home"] #hamburger span,
  body[data-page="home"] .menu-button span {
    position: static !important;
    display: block !important;
    width: 22px !important;
    height: 2px !important;
    background: #f5f8fc !important;
    border-radius: 2px !important;
    transition: transform .25s ease, opacity .25s ease !important;
    transform: none !important;
    top: auto !important;
    left: auto !important;
    right: auto !important;
  }
  body[data-page="home"] #hamburger.open span:nth-child(1),
  body[data-page="home"] .menu-button.open span:nth-child(1) {
    transform: translateY(7px) rotate(45deg) !important;
  }
  body[data-page="home"] #hamburger.open span:nth-child(2),
  body[data-page="home"] .menu-button.open span:nth-child(2) {
    opacity: 0 !important;
  }
  body[data-page="home"] #hamburger.open span:nth-child(3),
  body[data-page="home"] .menu-button.open span:nth-child(3) {
    transform: translateY(-7px) rotate(-45deg) !important;
  }

  /* Mobile Drawer Menu */
  body[data-page="home"] .mobile-drawer {
    display: block !important;
    position: fixed;
    top: 60px;
    left: 0;
    right: 0;
    background: rgba(4, 7, 12, 0.98);
    backdrop-filter: blur(24px);
    -webkit-backdrop-filter: blur(24px);
    border-bottom: 1px solid rgba(131, 192, 255, 0.2);
    max-height: 0;
    overflow: hidden;
    opacity: 0;
    transition: max-height .35s ease, opacity .25s ease;
    z-index: 9999;
    box-shadow: 0 20px 40px rgba(0, 0, 0, 0.7);
  }
  body[data-page="home"] .mobile-drawer.open {
    max-height: calc(100vh - 120px);
    opacity: 1;
    overflow-y: auto;
    padding: 1.25rem 1.5rem 2rem;
  }
  body[data-page="home"] .mobile-drawer__links {
    list-style: none;
    padding: 0;
    margin: 0;
  }
  body[data-page="home"] .mobile-drawer__links li {
    border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  }
  body[data-page="home"] .mobile-drawer__links a {
    display: flex;
    align-items: center;
    height: 44px;
    font-family: var(--font-body);
    font-size: 0.88rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--muted);
    text-decoration: none;
  }
  body[data-page="home"] .mobile-drawer__links a:hover,
  body[data-page="home"] .mobile-drawer__links a.active {
    color: var(--accent-soft);
  }
  body[data-page="home"] .mobile-drawer__cta {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
    margin-top: 1.5rem;
  }
  body[data-page="home"] .mobile-drawer__cta .button {
    width: 100%;
    min-height: 2.85rem;
  }
}

/* ============================================================
   RE-MEDIA LUXURY HERO SECTION (100% RESPONSIVE ON ALL DEVICES)
   ============================================================ */
body[data-page="home"] .re-hero {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100svh;
  padding: calc(var(--header-h, 76px) + 2.5rem) 1.25rem 4.5rem;
  overflow: hidden;
  background: #05080d;
  width: 100% !important;
  max-width: 100vw !important;
  box-sizing: border-box !important;
}

body[data-page="home"] .hero__media {
  position: absolute;
  inset: 0;
  overflow: hidden;
  z-index: 0;
  pointer-events: none;
}
body[data-page="home"] .hero__video {
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0.98;
  filter: brightness(0.92) contrast(1.05) saturate(1.18);
  transform: scale(1.02);
}
body[data-page="home"] .hero__video--desktop {
  display: block;
}
body[data-page="home"] .hero__video--mobile {
  display: none;
}
@media (max-width: 768px) {
  body[data-page="home"] .hero__video--desktop {
    display: none !important;
  }
  body[data-page="home"] .hero__video--mobile {
    display: block !important;
  }
}

body[data-page="home"] .hero__shade {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(180deg, rgba(4, 6, 10, 0.40) 0%, rgba(4, 6, 10, 0.08) 40%, rgba(4, 6, 10, 0.50) 100%),
    radial-gradient(circle at center, rgba(76, 146, 255, 0.06), transparent 60%);
  z-index: 1;
  pointer-events: none;
}

body[data-page="home"] .hero__grid {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(90deg, rgba(255, 255, 255, 0.03) 1px, transparent 0),
    linear-gradient(rgba(255, 255, 255, 0.03) 1px, transparent 0);
  background-size: 100px 100px;
