/* ==========================================================================
   ATENA CONTACT SECTION & CONSULTATION FORM
   ========================================================================== */
#contact {
  position: relative;
  z-index: 2;
  padding: 110px 0;
  background: #070d22;
}

.contact-grid {
  display: grid;
  grid-template-columns: 1fr 1.08fr;
  gap: clamp(40px, 6vw, 84px);
  align-items: center;
}

.contact-left .eyebrow {
  font-size: 0.76rem;
  letter-spacing: 0.32em;
  text-transform: uppercase;
  color: #39bce8;
  font-weight: 700;
  margin-bottom: 22px;
  display: inline-flex;
  align-items: center;
  gap: 12px;
}

.contact-left .eyebrow::before {
  content: "";
  width: 36px;
  height: 2px;
  background: #39bce8;
  display: inline-block;
  border-radius: 2px;
}

.contact-left h2 {
  font-size: clamp(2.2rem, 4.6vw, 3.8rem);
  margin-bottom: 24px;
  line-height: 1.15;
  color: #ffffff;
  font-family: 'Plus Jakarta Sans', var(--font-display), sans-serif;
  letter-spacing: -0.02em;
}

.contact-left p {
  color: rgba(232, 241, 253, 0.78);
  font-weight: 300;
  font-size: 1.08rem;
  max-width: 480px;
  margin-bottom: 36px;
  line-height: 1.6;
}

.cinfo {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.cinfo a, .cinfo div {
  display: flex;
  align-items: center;
  gap: 16px;
  font-size: 1.04rem;
  color: #e8f1fd;
  text-decoration: none;
  transition: color 0.25s ease;
}

.cinfo a:hover {
  color: #39bce8;
}

.cinfo .ci-ico {
  width: 46px;
  height: 46px;
  flex: 0 0 46px;
  border-radius: 50%;
  border: 1px solid rgba(156, 194, 251, 0.22);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #39bce8;
  background: rgba(13, 24, 56, 0.6);
  transition: all 0.3s ease;
}

.cinfo a:hover .ci-ico {
  background: rgba(57, 188, 232, 0.16);
  border-color: #39bce8;
  transform: translateY(-2px);
}

form.lead {
  padding: 42px 38px;
  border-radius: 22px;
  border: 1px solid rgba(156, 194, 251, 0.22);
  background: linear-gradient(160deg, rgba(22, 38, 84, 0.65), rgba(11, 20, 48, 0.55));
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  display: flex;
  flex-direction: column;
  gap: 20px;
  box-shadow: 0 25px 60px rgba(0, 0, 0, 0.45);
}

form.lead h3 {
  font-size: 1.85rem;
  color: #ffffff;
  margin-bottom: 4px;
  letter-spacing: -0.02em;
  font-weight: 700;
  font-family: 'Plus Jakarta Sans', var(--font-display), sans-serif;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.field label {
  font-size: 0.72rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: rgba(156, 194, 251, 0.85);
  font-weight: 600;
}

.field input, .field textarea, .field select {
  background: rgba(7, 13, 34, 0.65);
  border: 1px solid rgba(156, 194, 251, 0.22);
  border-radius: 12px;
  padding: 14px 18px;
  color: #ffffff;
  font-family: inherit;
  font-size: 0.98rem;
  transition: all 0.3s ease;
}

.field input:focus, .field textarea:focus, .field select:focus {
  outline: none;
  border-color: #39bce8;
  box-shadow: 0 0 0 3px rgba(57, 188, 232, 0.2);
}

.field select {
  cursor: pointer;
  appearance: none;
  -webkit-appearance: none;
  background-image: url("data:image/svg+xml;charset=UTF-8,%3csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%2339bce8' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'%3e%3cpolyline points='6 9 12 15 18 9'%3e%3c/polyline%3e%3c/svg%3e");
  background-repeat: no-repeat;
  background-position: right 16px center;
  background-size: 16px;
  padding-right: 42px;
}

.field select option {
  background: #0a1230;
  color: #ffffff;
  padding: 10px;
}

.field textarea {
  resize: vertical;
  min-height: 96px;
}

.row2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 18px;
}

.form-ok-msg {
  display: none;
  padding: 18px;
  border-radius: 12px;
  background: rgba(34, 197, 94, 0.15);
  border: 1px solid rgba(34, 197, 94, 0.35);
  color: #4ade80;
  font-weight: 600;
  text-align: center;
}

@media (max-width: 860px) {
  #contact {
    padding: 70px 0;
  }
  .contact-grid {
    grid-template-columns: 1fr;
    gap: 36px;
  }
  .row2 {
    grid-template-columns: 1fr;
    gap: 14px;
  }
