    linear-gradient(90deg, rgba(255, 255, 255, 0.03) 1px, transparent 0),
    linear-gradient(rgba(255, 255, 255, 0.03) 1px, transparent 0);
  background-size: 100px 100px;
  opacity: 0.22;
  -webkit-mask-image: linear-gradient(180deg, rgba(0, 0, 0, 0.5), transparent 100%);
  mask-image: linear-gradient(180deg, rgba(0, 0, 0, 0.5), transparent 100%);
  z-index: 1;
  pointer-events: none;
}

body[data-page="home"] .hero__orb {
  position: absolute;
  border-radius: 9999px;
  filter: blur(80px);
  pointer-events: none;
  z-index: 1;
  opacity: 0.16;
}
body[data-page="home"] .hero__orb--one {
  top: 15%;
  left: 50%;
  transform: translateX(-50%);
  width: min(650px, 90vw);
  height: 320px;
  background: radial-gradient(circle, rgba(76, 146, 255, 0.2), rgba(76, 146, 255, 0));
}
body[data-page="home"] .hero__orb--two {
  bottom: 10%;
  left: 50%;
  transform: translateX(-50%);
  width: min(500px, 80vw);
  height: 250px;
  background: radial-gradient(circle, rgba(131, 192, 255, 0.12), rgba(131, 192, 255, 0));
}

body[data-page="home"] .hero__fade {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 78%, #05080d 100%);
  z-index: 1;
  pointer-events: none;
}

body[data-page="home"] .hero__content {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: center;
