  letter-spacing: -0.025em;
  color: #ffffff;
  font-weight: 900;
  text-transform: uppercase;
  text-shadow: 0 4px 24px rgba(0, 0, 0, 0.92), 0 2px 6px rgba(0, 0, 0, 0.95), 0 10px 40px rgba(0, 0, 0, 0.85);
