  display: grid !important;
  grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
  gap: 0.85rem !important;
}

/* Featured Work Tile */
.featured-work__tile {
  position: relative !important;
  overflow: hidden !important;
  border-radius: 22px !important;
  border: 1px solid rgba(255, 255, 255, 0.08) !important;
  background: #04070c !important;
  box-shadow: 0 24px 72px rgba(0, 0, 0, 0.28) !important;
  cursor: pointer !important;
  aspect-ratio: 10 / 16 !important;
  transition: transform 0.35s cubic-bezier(0.16, 1, 0.3, 1), border-color 0.35s ease, box-shadow 0.35s ease !important;
}

.featured-work__tile:hover {
  transform: translateY(-4px) !important;
  border-color: rgba(131, 192, 255, 0.38) !important;
  box-shadow: 0 28px 80px rgba(0, 0, 0, 0.45) !important;
}

.featured-work__tile .media-shell {
  position: relative !important;
  width: 100% !important;
  height: 100% !important;
  border-radius: inherit !important;
  background: #09101a !important;
  overflow: hidden !important;
}

.featured-work__tile-asset {
  width: 100% !important;
  height: 100% !important;
  object-fit: cover !important;
  transform: scale(1.01) !important;
  opacity: 0.78 !important;
  filter: saturate(0.95) brightness(0.78) !important;
  transition: transform 0.45s ease, opacity 0.45s ease, filter 0.45s ease !important;
}

.featured-work__tile:hover .featured-work__tile-asset {
  transform: scale(1.04) !important;
  opacity: 0.98 !important;
  filter: saturate(1.05) brightness(0.94) !important;
}

.featured-work__tile-overlay {
  position: absolute !important;
  inset: 0 !important;
  background: linear-gradient(180deg, rgba(2, 4, 8, 0.08) 0%, rgba(2, 4, 8, 0.3) 58%, rgba(2, 4, 8, 0.52) 100%) !important;
  pointer-events: none !important;
}

.featured-work__tile-cta {
  position: absolute !important;
  inset: 0 !important;
  z-index: 2 !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  opacity: 0 !important;
  pointer-events: none !important;
  transition: opacity 0.28s ease !important;
}

.featured-work__tile:hover .featured-work__tile-cta,
.featured-work__tile:focus-within .featured-work__tile-cta {
  opacity: 1 !important;
  pointer-events: auto !important;
}

.featured-work__tile-button {
  min-height: 2.15rem !important;
  padding: 0 1.15rem !important;
  border: 1px solid rgba(131, 192, 255, 0.32) !important;
  border-radius: 999px !important;
  background: linear-gradient(135deg, rgba(76, 146, 255, 0.92), rgba(131, 192, 255, 0.9)) !important;
  color: #05101b !important;
  font-size: 0.62rem !important;
  font-weight: 800 !important;
  letter-spacing: 0.16em !important;
  text-transform: uppercase !important;
  box-shadow: 0 14px 36px rgba(0, 0, 0, 0.34) !important;
  cursor: pointer !important;
  transition: transform 0.22s ease, background 0.22s ease, border-color 0.22s ease !important;
}

.featured-work__tile-button:hover {
  transform: translateY(-1px) !important;
  border-color: rgba(215, 235, 255, 0.54) !important;
  background: linear-gradient(135deg, rgba(131, 192, 255, 0.96), rgba(215, 235, 255, 0.92)) !important;
}

/* Lightbox Preview Modal (re-media.co exact style) */
.featured-work-preview {
  position: fixed !important;
  inset: 0 !important;
  z-index: 99999 !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  padding: clamp(0.75rem, 2vw, 1.5rem) !important;
  background: rgba(0, 0, 0, 0.88) !important;
  backdrop-filter: blur(16px) !important;
  -webkit-backdrop-filter: blur(16px) !important;
}

.featured-work-preview__panel {
  display: flex !important;
  flex-direction: column !important;
  width: min(100%, 78rem) !important;
  max-height: calc(100svh - 2rem) !important;
  padding: 1rem !important;
  border: 1px solid rgba(255, 255, 255, 0.1) !important;
  border-radius: 28px !important;
  background: #04070c !important;
  box-shadow: 0 26px 90px rgba(0, 0, 0, 0.5) !important;
  box-sizing: border-box !important;
}

.featured-work-preview__panel--portrait {
  width: min(100%, 28rem) !important;
}

.featured-work-preview__head {
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
  gap: 1rem !important;
  margin-bottom: 0.75rem !important;
}

.featured-work-preview__eyebrow {
  margin: 0 !important;
  color: #83c0ff !important;
  font-size: 0.72rem !important;
  font-weight: 800 !important;
  letter-spacing: 0.22em !important;
  text-transform: uppercase !important;
}

.featured-work-preview__close {
  min-height: 2.15rem !important;
  padding: 0 1rem !important;
  border: 1px solid rgba(255, 255, 255, 0.12) !important;
  border-radius: 999px !important;
  background: rgba(255, 255, 255, 0.06) !important;
  color: #ffffff !important;
  font-size: 0.68rem !important;
  font-weight: 800 !important;
  letter-spacing: 0.16em !important;
  text-transform: uppercase !important;
  cursor: pointer !important;
  transition: background 0.2s, border-color 0.2s !important;
}

.featured-work-preview__close:hover {
  background: rgba(255, 255, 255, 0.14) !important;
  border-color: rgba(255, 255, 255, 0.25) !important;
}

.featured-work-preview__stage {
  display: flex !important;
  flex: 1 !important;
  align-items: center !important;
  justify-content: center !important;
  min-height: 0 !important;
  padding: 0.4rem !important;
  overflow: hidden !important;
  border-radius: 20px !important;
  background: radial-gradient(circle at top, rgba(131, 192, 255, 0.08), transparent 55%), #02060b !important;
}

.featured-work-preview__media {
  display: block !important;
  width: 100% !important;
  max-height: 72vh !important;
  border-radius: 16px !important;
  object-fit: cover !important;
}

/* Mobile Responsive (< 1080px) */
@media (max-width: 1080px) {
  .featured-work__middle {
    grid-template-columns: 1fr !important;
    gap: 1.75rem !important;
  }

  .home-offer-section .section-heading {
    margin-bottom: 1.75rem !important;
  }

  .home-offer-section .section-title {
    font-size: clamp(28px, 7vw, 38px) !important;
  }

  .featured-work__reels,
  .featured-work__trust {
    grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
    gap: 0.8rem !important;
  }

  .featured-work__tile {
    border-radius: 20px !important;
    aspect-ratio: 10 / 16 !important;
  }

  .featured-work__tile-cta {
    opacity: 0.88 !important;
    align-items: flex-end !important;
    padding-bottom: 0.85rem !important;
  }

  .featured-work__tile-button {
    font-size: 0.52rem !important;
    min-height: 1.85rem !important;
    padding: 0 0.85rem !important;
  }
}


