/* Featured Work Layout - 2 columns on desktop, exactly 4 reels in one row! */
.featured-work {
  display: grid !important;
  gap: 2.05rem !important;
  width: 100% !important;
}

.featured-work__middle {
  display: grid !important;
  grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
  gap: 1.25rem !important;
  align-items: start !important;
}

.featured-work__group {
  display: grid !important;
  gap: 0.95rem !important;
}

.featured-work__header {
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  text-align: center !important;
  padding-bottom: 0.35rem !important;
}

.featured-work__header-copy {
  display: grid !important;
  gap: 0.35rem !important;
  justify-items: center !important;
}

.featured-work__header-label {
  margin: 0 !important;
  color: rgba(245, 248, 252, 0.96) !important;
